{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Structured coaching for sustainable energy, clarity, and daily habits. VIP Day and multi-week programs with {{COACH_NAME}}, {{CREDENTIALS}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="site">
  <header class="site-header">
    <div class="container header-grid">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" aria-label="Primary">
        <ul>
          <li><a href="about.html">About</a></li>
          <li><a href="programs.html">Programs</a></li>
          <li><a href="services.html">Services</a></li>
          <li><a href="pricing.html">Pricing</a></li>
          <li><a href="testimonials.html">Stories</a></li>
          <li><a href="book.html">Book</a></li>
          <li><a href="contact.html">Contact</a></li>
        </ul>
      </nav>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <button class="nav-toggle" aria-label="Open menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero container grid-2">
      <div class="hero-copy">
        <h1>Practical rhythms for consistent wellbeing</h1>
        <p class="lead">I help busy people build simple daily systems that boost energy, focus, and resilience — without burnout. Evidence-informed frameworks, habit design, and compassionate accountability.</p>
        <ul class="hero-quick">
          <li><strong>1:1 VIP Day</strong> — deep reset and roadmap</li>
          <li><strong>12-week Path</strong> — habit architecture + coaching</li>
          <li><strong>Core Tools</strong> — routines you keep</li>
        </ul>
        <div class="hero-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="#lead-magnet">Get the Habit Kit</a>
        </div>
        <p class="meta">Work with {{COACH_NAME}}, {{CREDENTIALS}} — serving clients in {{CITY}}, {{STATE}} and remote.</p>
      </div>
      <div class="hero-art">
        <img src="assets/img/hero.svg" alt="Abstract wellness illustration"/>
        <div class="avatar">
          <img src="assets/img/avatar.svg" alt="{{COACH_NAME}} avatar"/>
          <div class="avatar-text">{{COACH_NAME}}, {{CREDENTIALS}}</div>
        </div>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social-proof container">
      <h2>Trusted by professionals who needed a reset</h2>
      <div class="proof-grid">
        <figure>
          <blockquote>"A clear plan I could follow — and actually stick to."</blockquote>
          <figcaption>- Jordan P., Product Lead</figcaption>
        </figure>
        <figure>
          <blockquote>"Better sleep and less decision fatigue in 2 weeks."</blockquote>
          <figcaption>- Maya R., Creative Director</figcaption>
        </figure>
        <figure>
          <blockquote>"The VIP Day changed my relationship to rest."</blockquote>
          <figcaption>- Sam K., Entrepreneur</figcaption>
        </figure>
      </div>
    </section>

    <!-- BENEFITS -->
    <section class="benefits container">
      <header class="section-head">
        <h3>Small habits. Measurable shifts.</h3>
        <p>Programs focus on three consistent outcomes so you can measure progress and sustain change.</p>
      </header>
      <div class="cards">
        <article class="card">
          <h4>Consistent Energy</h4>
          <p>Daily routines that stabilise energy across the day — no extremes, just steadiness.</p>
        </article>
        <article class="card">
          <h4>Clear Priorities</h4>
          <p>Frameworks that help you pick what matters and let go of the rest.</p>
        </article>
        <article class="card">
          <h4>Sustainable Habits</h4>
          <p>Micro-steps that stack into reliable practices you actually keep long term.</p>
        </article>
      </div>
    </section>

    <!-- PROCESS -->
    <section class="process container">
      <h3>How a typical engagement flows</h3>
      <ol class="process-list">
        <li><strong>Discovery</strong> — clarify current patterns and goals.</li>
        <li><strong>Design</strong> — a personalized rhythm with weekly anchors.</li>
        <li><strong>Practice</strong> — guided implementation with micro-adjustments.</li>
        <li><strong>Consolidate</strong> — habits become stable and self-sustaining.</li>
      </ol>
      <p class="process-note">Each step includes measurable checkpoints so you see progress every 1-4 weeks.</p>
    </section>

    <!-- FAQ -->
    <section class="faq container">
      <h3>Questions people usually ask</h3>
      <div class="faq-grid">
        <div class="faq-item">
          <button class="faq-q">What is the VIP Day and who is it for?</button>
          <div class="faq-a">The VIP Day is an intensive one-on-one session focused on mapping your routine, eliminating friction, and creating a 30-day starter plan. It's ideal if you want rapid clarity and a concrete plan to act on immediately.</div>
        </div>
        <div class="faq-item">
          <button class="faq-q">Do you provide ongoing accountability?</button>
          <div class="faq-a">Yes — multi-week programs include weekly coaching touchpoints and habit tracking. VIP clients can add follow-up check-ins.</div>
        </div>
        <div class="faq-item">
          <button class="faq-q">Can coaching address sleep and stress?</button>
          <div class="faq-a">Coaching focuses on behavioral frameworks and habit design that influence sleep and stress in practical, non-medical ways. Any clinical concerns are referred to appropriate specialists.</div>
        </div>
      </div>
    </section>

    <!-- LEAD MAGNET -->
    <section id="lead-magnet" class="lead-magnet container">
      <div class="magnet-grid">
        <div>
          <h3>Free Habit Kit: 7 actionable steps to stabilise your week</h3>
          <p>Download a concise planner, checklist, and a short walkthrough that you can use this week to test one key habit.</p>
          <form id="magnet-form" class="magnet-form">
            <label for="email">Email</label>
            <input id="email" name="email" type="email" placeholder="you@domain.com" required>
            <button class="btn primary" type="submit">Send me the Habit Kit</button>
          </form>
          <p class="small">By signing up you'll also receive occasional tips and program updates. You can unsubscribe anytime.</p>
        </div>
        <div class="magnet-art">
          <img src="assets/img/pattern.svg" alt="pattern"/>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta container">
      <div class="cta-inner">
        <h3>Ready to build a rhythm that lasts?</h3>
        <p>Start with a discovery conversation and we’ll find the right path — VIP Day, 12-week program, or flexible coaching.</p>
        <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a class="btn ghost" href="book.html">Schedule a Discovery</a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{TAGLINE}}</p>
      </div>
      <div class="contact">
        <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        <p>{{CITY}}, {{STATE}}</p>
      </div>
      <div class="mini-cta">
        <p>Free resource</p>
        <a class="btn small" href="#lead-magnet">Get Habit Kit</a>
      </div>
    </div>
    <div class="credit">© <span id="year"></span> {{BUSINESS_NAME}} • All rights reserved.</div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
