{"path":"assets/css/styles.css","content":"/* Clinic Modern — core styles */
:root{
  --bg:#fbfdff; --card:#ffffff; --muted:#6b7280; --accent:#0f766e; --accent-2:#06b6d4; --text:#0f172a; --radius:10px; --shadow:0 6px 18px rgba(15,23,42,0.08);
  --container:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; margin:0; color:var(--text); background:var(--bg);}
.container{max-width:var(--container); margin:0 auto; padding:48px 20px}
.header-grid{display:grid; grid-template-columns:1fr auto auto; gap:20px; align-items:center}
.brand{font-weight:700; color:var(--text); text-decoration:none}
.nav ul{display:flex; gap:18px; list-style:none; margin:0; padding:0}
.nav a{color:var(--muted); text-decoration:none}
.cta{background:transparent; border:1px solid var(--accent); padding:8px 14px; border-radius:8px; color:var(--accent); text-decoration:none}
.nav-toggle{display:none}

/* Hero */
.hero.grid-2{display:grid; grid-template-columns:1fr 420px; gap:40px; align-items:center}
.hero-copy h1{font-size:32px; margin:0 0 12px}
.lead{color:var(--muted); font-size:16px; margin-bottom:16px}
.hero-quick{display:flex; gap:12px; padding:0; list-style:none; margin:12px 0}
.hero-quick li{background:var(--card); padding:8px 12px; border-radius:8px; box-shadow:var(--shadow); font-size:14px}
.hero-actions{display:flex; gap:12px; margin-top:16px}
.btn{display:inline-block; padding:10px 18px; border-radius:10px; text-decoration:none; font-weight:600}
.btn.primary{background:var(--accent); color:white}
.btn.ghost{background:transparent; border:1px solid rgba(15,23,42,0.06); color:var(--text)}
.btn.large{padding:14px 22px; font-size:16px}
.meta{color:var(--muted); font-size:13px; margin-top:12px}
.hero-art{position:relative}
.hero-art img{width:100%; height:auto; border-radius:12px; box-shadow:var(--shadow)}
.avatar{position:absolute; bottom:-24px; left:16px; display:flex; align-items:center; background:var(--card); border-radius:12px; padding:8px; box-shadow:var(--shadow);}
.avatar img{width:56px; height:56px; border-radius:8px}
.avatar-text{margin-left:10px; font-size:14px}

/* Social proof */
.social-proof h2{margin:0 0 16px}
.proof-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:16px}
.proof-grid figure{background:var(--card); padding:18px; border-radius:10px; box-shadow:var(--shadow);}
.proof-grid blockquote{margin:0 0 8px; font-style:italic}

/* Benefits */
.benefits .section-head{margin-bottom:12px}
.cards{display:grid; grid-template-columns:repeat(3,1fr); gap:16px}
.card{background:var(--card); padding:18px; border-radius:12px; box-shadow:var(--shadow)}

/* Process */
.process-list{counter-reset:step; display:grid; gap:12px}
.process-list li{list-style:none; padding:12px; background:var(--card); border-radius:10px; box-shadow:var(--shadow)}
.process-list li::before{counter-increment:step; content:counter(step); display:inline-block; width:28px; height:28px; line-height:28px; text-align:center; margin-right:10px; background:var(--accent); color:white; border-radius:50%}

/* FAQ */
.faq-grid{display:grid; grid-template-columns:repeat(2,1fr); gap:12px}
.faq-item{background:var(--card); padding:12px; border-radius:10px; box-shadow:var(--shadow)}
.faq-q{width:100%; text-align:left; background:none; border:none; padding:0; font-weight:600; cursor:pointer}
.faq-a{margin-top:8px; display:none; color:var(--muted)}

/* Lead magnet */
.lead-magnet .magnet-grid{display:grid; grid-template-columns:1fr 320px; gap:20px; align-items:center}
.magnet-form{display:flex; gap:10px; flex-direction:column; margin-top:12px}
.magnet-form input{padding:10px; border-radius:8px; border:1px solid #e6eef0}
.small{font-size:13px; color:var(--muted)}

/* CTA */
.final-cta{background:linear-gradient(90deg, rgba(6,182,212,0.08), rgba(15,118,110,0.04)); padding:40px; border-radius:12px; text-align:center}

/* Footer */
.site-footer{background:transparent; padding:28px 0 60px}
.footer-grid{display:grid; grid-template-columns:1fr auto auto; gap:20px; align-items:start}
.credit{color:var(--muted); text-align:center; margin-top:18px}

/* Responsive */
@media (max-width:900px){
  .hero.grid-2{grid-template-columns:1fr}
  .proof-grid{grid-template-columns:1fr}
  .cards{grid-template-columns:1fr}
  .faq-grid{grid-template-columns:1fr}
  .lead-magnet .magnet-grid{grid-template-columns:1fr}
  .nav ul{display:none}
  .nav-toggle{display:block}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // small interactions for clinic_modern site
  document.getElementById('year').textContent = new Date().getFullYear();

  // nav toggle for mobile
  var toggle = document.querySelector('.nav-toggle');
  var nav = document.querySelector('.nav ul');
  if(toggle){
    toggle.addEventListener('click', function(){
      if(nav.style.display === 'flex'){ nav.style.display = ''; }
      else{ nav.style.display = 'flex'; nav.style.flexDirection = 'column'; }
    });
  }

  // FAQ accordion
  Array.prototype.slice.call(document.querySelectorAll('.faq-q')).forEach(function(btn){
    btn.addEventListener('click', function(){
      var a = this.nextElementSibling;
      if(a.style.display === 'block'){ a.style.display = ''; }
      else{ a.style.display = 'block'; }
    });
  });

  // Lead magnet form faux submit
  var form = document.getElementById('magnet-form');
  if(form){
    form.addEventListener('submit', function(e){
      e.preventDefault();
      var email = form.email.value;
      if(!email) return;
      // simple feedback
      var btn = form.querySelector('button');
      btn.disabled = true;
      btn.textContent = 'Sending...';
      setTimeout(function(){
        btn.textContent = 'Check your inbox';
        form.email.value = '';
        btn.classList.add('sent');
      }, 900);
    });
  }

})();"} 
